def borrow_book(member, create_loan):
    canonical_id = member.get("member_id")
    if not isinstance(canonical_id, str) or not canonical_id.strip():
        return {"status": "invalid", "error": "missing_member_id"}
    receipt_id = create_loan(member)
    return {"status": "borrowed", "receipt_id": receipt_id}
